macro_rules! AllocMap {
    () => {
        # [doc = " The functionality needed by memory to manage its allocations"] pub trait AllocMap < K : Hash + Eq , V > { # [doc = " Tests if the map contains the given key."] # [doc = " Deliberately takes `&mut` because that is sufficient, and some implementations"] # [doc = " can be more efficient then (using `RefCell::get_mut`)."] fn contains_key < Q : ? Sized + Hash + Eq > (& mut self , k : & Q) -> bool where K : Borrow < Q > ; # [doc = " Callers should prefer [`AllocMap::contains_key`] when it is possible to call because it may"] # [doc = " be more efficient. This function exists for callers that only have a shared reference"] # [doc = " (which might make it slightly less efficient than `contains_key`, e.g. if"] # [doc = " the data is stored inside a `RefCell`)."] fn contains_key_ref < Q : ? Sized + Hash + Eq > (& self , k : & Q) -> bool where K : Borrow < Q > ; # [doc = " Inserts a new entry into the map."] fn insert (& mut self , k : K , v : V) -> Option < V > ; # [doc = " Removes an entry from the map."] fn remove < Q : ? Sized + Hash + Eq > (& mut self , k : & Q) -> Option < V > where K : Borrow < Q > ; # [doc = " Returns data based on the keys and values in the map."] fn filter_map_collect < T > (& self , f : impl FnMut (& K , & V) -> Option < T >) -> Vec < T > ; # [doc = " Returns a reference to entry `k`. If no such entry exists, call"] # [doc = " `vacant` and either forward its error, or add its result to the map"] # [doc = " and return a reference to *that*."] fn get_or < E > (& self , k : K , vacant : impl FnOnce () -> Result < V , E >) -> Result < & V , E > ; # [doc = " Returns a mutable reference to entry `k`. If no such entry exists, call"] # [doc = " `vacant` and either forward its error, or add its result to the map"] # [doc = " and return a reference to *that*."] fn get_mut_or < E > (& mut self , k : K , vacant : impl FnOnce () -> Result < V , E >) -> Result < & mut V , E > ; # [doc = " Read-only lookup."] fn get (& self , k : K) -> Option < & V > { self . get_or (k , | | Err (())) . ok () } # [doc = " Mutable lookup."] fn get_mut (& mut self , k : K) -> Option < & mut V > { self . get_mut_or (k , | | Err (())) . ok () } }
    };
}

AllocMap!();